INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki-v2:2026-09-24','2026-09-24',2026,9,24,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-09-24T02:53:00-CME-001","note":"CME observed to the E only in STEREO A COR2, likely not seen in other coronagraphs due to the occulting disk and/or faint leading edge. The start time of 2026-09-24T02:53Z in white light is later than the first observation at 2026-09-24T01:38Z in running difference imagery due to the bright streamer overlap. The source may be an eruption from AR 14536 centered around N03W32, observed as slow dimming, brightening, and field line movement in SDO AIA 171/193 starting around 2026-09-23T21:06Z. In ST","cme_type":"C","speed_kps":500,"start_time":"2026-09-24T02:53Z","half_angle_deg":10,"source_location":"N03W32"},{"id":"2026-09-24T09:23:00-CME-001","note":"Faint CME observed to the SW only in STEREO A COR2, may be due to faintness or the occulting disk in other coronagraphs. No EUV source is observed for this front.","cme_type":"C","speed_kps":618,"start_time":"2026-09-24T09:23Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-24T14:45:00-CME-001","note":"CME observed to the SW in GOES CCOR-1 and S in STEREO A COR2, overlapping with a slow, wide streamer blowout beginning ~2026-09-23T20:12Z (itself measuring ~176 km/s). Not observed in SOHO LASCO C2/C3 due to a real-time data gap. The source is field line movement and small shifting of a coronal hole boundary best observed only in GOES SUVI 284 starting ~2026-09-24T14:02Z, tracing on-disk around S35W70 in proximity to a large southern coronal hole.","cme_type":"S","speed_kps":493,"start_time":"2026-09-24T14:45Z","half_angle_deg":29,"source_location":"S35W70"}],"level":"Moderate","counts":{"cmes":3,"flares":0,"storms":0},"flares":[],"max_kp":null,"status":"ok","storms":[],"window_end":"2026-09-24","window_start":"2026-09-22","max_flare_class":null},"cache_key":"donki-v2:2026-09-24","created_at":"2026-09-28T11:39:52.733855+00:00","expires_at":"2026-09-28T11:54:52.561+00:00","updated_at":"2026-09-28T11:39:52.561+00:00","request_date":"2026-09-24"}','2026-09-28T11:39:52.561+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki-v2:2026-09-28','2026-09-28',2026,9,28,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-09-26T00:48:00-CME-001","note":"Faint CME first seen to the NE by SOHO LASCO C2 beginning at 2026-09-26T00:48Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1. There is no clear source for this event as it is likely far sided.","cme_type":"S","speed_kps":478,"start_time":"2026-09-26T00:48Z","half_angle_deg":15,"source_location":""},{"id":"2026-09-26T02:24:00-CME-001","note":"Faint CME first seen to the NE by SOHO LASCO C2 beginning at 2026-09-26T02:24Z, as well as by SOHO LASCO C3 and STEREO A COR2 in later frames. This CME is obscured by Earthshine in GOES CCOR-1. There is no clear source seen for this event as it is likely far sided.","cme_type":"S","speed_kps":417,"start_time":"2026-09-26T02:24Z","half_angle_deg":13,"source_location":""},{"id":"2026-09-26T15:24:00-CME-001","note":"Faint minor CME with a pointy front seen to the NE in SOHO LASCO C2/C3 and GOES CCOR-1 but not seen in STEREO A COR2 coronagraph.","cme_type":"S","speed_kps":449,"start_time":"2026-09-26T15:24Z","half_angle_deg":13,"source_location":""},{"id":"2026-09-26T19:36:00-CME-001","note":"Bright lightbulb-shaped CME seen to the SW in SOHO LASCO C2/C3, GOES CCOR-1 and STEREO A COR2. Its source is a large prominence seen lifting from behind the SW limb starting at 2026-09-26T18:28Z (best seen in GOES SUVI 304), with source location seen on disk, close to the SW limb in STEREO A EUV 304/195 imagery. In EUV A 195 imagery we see an ejecta, as well as dimming and bright post-eruptive arcades. The erupting filament is also seen in AIA 171 and faintly in AIA 304, and ejecta and opening o","cme_type":"S","speed_kps":427,"start_time":"2026-09-26T19:36Z","half_angle_deg":34,"source_location":"S20W135"},{"id":"2026-09-26T20:00:00-CME-001","note":"A minor faint CME seen to the NE in GOES CCOR-1 and SOHO LASCO C3, and not seen in STEREO A COR2 coronagraph. No source has been found in EUV imagery for this CME, so it is likely far-sided.","cme_type":"S","speed_kps":336,"start_time":"2026-09-26T20:00Z","half_angle_deg":19,"source_location":""},{"id":"2026-09-27T06:36:00-CME-001","note":"CME first seen to the West by SOHO LASCO C2 beginning at 2026-09-27T06:36Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is a small eruption from the vicinity of AR 14534 (N10W95) beginning at approx. 2026-09-27T04:30Z in STEREO A EUVI 195. This CME is likely deflected to the West by a large coronal hole in the vicinity of the eruption.","cme_type":"S","speed_kps":399,"start_time":"2026-09-27T06:36Z","half_angle_deg":17,"source_location":"N10W95"},{"id":"2026-09-27T07:00:00-CME-001","note":"CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-27T07:00Z as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is minor field line movement and brightening seen located at approx. S30W100-120 beginning at 2026-09-27T06:00Z as seen in STEREO A EUVI 195.","cme_type":"C","speed_kps":606,"start_time":"2026-09-27T07:00Z","half_angle_deg":28,"source_location":"S30W110"},{"id":"2026-09-27T09:48:00-CME-001","note":"Narrow CME first seen to the NNE by SOHO LASCO C2 beginning at 2026-09-27T09:48Z, as well as by SOHO LASCO C3, GOES CCOR-1 and to the North by STEREO A COR2. There is no clear source seen for this event as it is likely far sided.","cme_type":"S","speed_kps":352,"start_time":"2026-09-27T09:48Z","half_angle_deg":15,"source_location":""}],"level":"Moderate","counts":{"cmes":14,"flares":0,"storms":0},"flares":[],"max_kp":null,"status":"ok","storms":[],"window_end":"2026-09-28","window_start":"2026-09-26","max_flare_class":null},"cache_key":"donki-v2:2026-09-28","created_at":"2026-09-28T11:39:47.308365+00:00","expires_at":"2026-09-28T16:36:43.17+00:00","updated_at":"2026-09-28T16:21:43.17+00:00","request_date":"2026-09-28"}','2026-09-28T16:21:43.17+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki-v2:2026-09-29','2026-09-29',2026,9,29,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-09-27T06:36:00-CME-001","note":"CME first seen to the West by SOHO LASCO C2 beginning at 2026-09-27T06:36Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is a small eruption from the vicinity of AR 14534 (N10W95) beginning at approx. 2026-09-27T04:30Z in STEREO A EUVI 195. This CME is likely deflected to the West by a large coronal hole in the vicinity of the eruption.","cme_type":"S","speed_kps":399,"start_time":"2026-09-27T06:36Z","half_angle_deg":17,"source_location":"N10W95"},{"id":"2026-09-27T07:00:00-CME-001","note":"CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-27T07:00Z as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is minor field line movement and brightening seen located at approx. S30W100-120 beginning at 2026-09-27T06:00Z as seen in STEREO A EUVI 195.","cme_type":"C","speed_kps":606,"start_time":"2026-09-27T07:00Z","half_angle_deg":28,"source_location":"S30W110"},{"id":"2026-09-27T09:48:00-CME-001","note":"Narrow CME first seen to the NNE by SOHO LASCO C2 beginning at 2026-09-27T09:48Z, as well as by SOHO LASCO C3, GOES CCOR-1 and to the North by STEREO A COR2. There is no clear source seen for this event as it is likely far sided.","cme_type":"S","speed_kps":352,"start_time":"2026-09-27T09:48Z","half_angle_deg":15,"source_location":""},{"id":"2026-09-27T14:48:00-CME-001","note":"Narrow, faint CME first seen to the NE by SOHO LASCO C2 beginning at 2026-09-27T14:48Z, as well as by SOHO LASCO C3 and GOES CCOR-1 in later frames. This CME is not clearly seen in STEREO A COR2 imagery. There is no clear source seen for this event as it is likely far sided, but some faint field line movement can be seen beyond the NE limb in SDO AIA 171 beginning at approx. 2026-09-27T13:45Z.","cme_type":"S","speed_kps":283,"start_time":"2026-09-27T14:48Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-27T17:36:00-CME-001","note":"Faint CME observed to the NE in SOHO LASCO C2/C3 and GOES CCOR-1, not observed in STEREO A COR2. The source may be far-sided, observed as slow field line movement over the NE limb in SDO AIA 171 starting around 2026-09-27T15:48Z.","cme_type":"S","speed_kps":403,"start_time":"2026-09-27T17:36Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-27T21:00:00-CME-001","note":"Faint CME observed to the NE in SOHO LASCO C2/C3 and GOES CCOR-1, not observed in STEREO A COR2. The source may be on/just beyond the SW limb observed in SDO AIA 171, with two close candidates of field line movement around 2026-09-28T19:51Z and/or 2026-09-27T20:25Z a few degrees to the north.","cme_type":"S","speed_kps":362,"start_time":"2026-09-27T21:00Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-28T01:26:00-CME-001","note":"Narrow CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-28T01:26Z as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is an eruption seen along the SW limb in STEREO A EUVI 304 beginning at approx. 2026-09-28T01:00Z.","cme_type":"S","speed_kps":435,"start_time":"2026-09-28T01:26Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-28T04:12:00-CME-001","note":"Faint CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-28T04:12Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. There is no clear source seen for this event.","cme_type":"S","speed_kps":403,"start_time":"2026-09-28T04:12Z","half_angle_deg":16,"source_location":""}],"level":"Moderate","counts":{"cmes":14,"flares":0,"storms":0},"flares":[],"max_kp":null,"status":"ok","storms":[],"window_end":"2026-09-29","window_start":"2026-09-27","max_flare_class":null},"cache_key":"donki-v2:2026-09-29","created_at":"2026-09-29T04:04:38.417472+00:00","expires_at":"2026-09-29T13:25:31.99+00:00","updated_at":"2026-09-29T13:10:31.99+00:00","request_date":"2026-09-29"}','2026-09-29T13:10:31.99+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki-v2:2026-09-30','2026-09-30',2026,9,30,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-09-28T01:26:00-CME-001","note":"Narrow CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-28T01:26Z as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is an eruption seen along the SW limb in STEREO A EUVI 304 beginning at approx. 2026-09-28T01:00Z.","cme_type":"S","speed_kps":435,"start_time":"2026-09-28T01:26Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-28T04:12:00-CME-001","note":"Faint CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-28T04:12Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. There is no clear source seen for this event.","cme_type":"S","speed_kps":403,"start_time":"2026-09-28T04:12Z","half_angle_deg":16,"source_location":""},{"id":"2026-09-28T04:24:00-CME-001","note":"Narrow CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-28T04:24Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is faint field line opening seen along the SW limb (approx. W140) in STEREO A EUVI 195 beginning at approx. 2026-09-28T03:35Z.","cme_type":"S","speed_kps":430,"start_time":"2026-09-28T04:24Z","half_angle_deg":14,"source_location":""},{"id":"2026-09-28T14:36:00-CME-001","note":"Bright loop CME first seen to the West by SOHO LASCO C2 beginning at 2026-09-28T14:36Z, as well as by SOHO LASCO C3 and GOES CCOR-1, as well as to the East in STEREO A COR2 in later frames. The source of this event is a very large filament eruption seen stretching from approx. S10W50 to N45W50 (centered at approx. N27W50) with liftoff beginning at approx. 2026-09-28T13:51Z as seen in SDO AIA, STEREO A EUVI and GOES SUVI 304. Post eruptive arcades, dimming and wide field line opening can be seen ","cme_type":"S","speed_kps":447,"start_time":"2026-09-28T14:36Z","half_angle_deg":45,"source_location":"N27W50"},{"id":"2026-09-28T16:18:00-CME-001","note":"Faint CME seen to the SE by SOHO LASCO C2 beginning at 2026-09-28T16:18Z, as well as by SOHO LASCO C3 and GOES CCOR-1 in later frames. This CME is not clearly seen in STEREO A COR2 as it is likely obscured by the pylon. The source of this CME is faint field line opening seen originating from beyond the SW limb in SDO AIA 171 beginning at approx. 2026-09-28T15:45Z.","cme_type":"C","speed_kps":581,"start_time":"2026-09-28T16:18Z","half_angle_deg":10,"source_location":""},{"id":"2026-09-28T21:24:00-CME-001","note":"Faint CME observed to the NW in SOHO LASCO C2/C3 and GOES CCOR-1, not observed in STEREO A COR2. The source could be field line movement on/just beyond the NW limb, perhaps former AR 14536, in GOES SUVI 284 starting around 2026-09-28T21:46Z, but this field line movement starts just after the CME is first observed in LASCO C2. It may also be outflow following filament eruption CME: 2026-09-28T14:36Z.","cme_type":"S","speed_kps":386,"start_time":"2026-09-28T21:24Z","half_angle_deg":27,"source_location":""},{"id":"2026-09-29T04:12:00-CME-001","note":"This CME is visible to the east in SOHO LASCO C2/C3 and GOES CCOR-1 imagery for a few early frames before becoming too diffuse to observe. This event is not visible in STEREO A COR2 imagery. The source is likely related to an eruption seen on or slightly beyond the eastern limb in SDO AIA/GOES SUVI 304 imagery starting around 2026-09-29T03:50Z.","cme_type":"C","speed_kps":655,"start_time":"2026-09-29T04:12Z","half_angle_deg":10,"source_location":"S05E90"},{"id":"2026-09-29T07:12:00-CME-001","note":"This CME is visible to the east in SOHO LASCO C2/C3 and GOES CCOR-1 imagery for a few early frames before becoming too diffuse to observe. This event is not visible in STEREO A COR2 imagery. The source is likely related to an eruption seen on or slightly beyond the eastern limb in SDO AIA/GOES SUVI 304 imagery starting around 2026-09-29T07:00Z.","cme_type":"C","speed_kps":958,"start_time":"2026-09-29T07:12Z","half_angle_deg":10,"source_location":"S09W90"}],"level":"Moderate","counts":{"cmes":9,"flares":0,"storms":0},"flares":[],"max_kp":null,"status":"ok","storms":[],"window_end":"2026-09-30","window_start":"2026-09-28","max_flare_class":null},"cache_key":"donki-v2:2026-09-30","created_at":"2026-09-30T00:28:01.898065+00:00","expires_at":"2026-09-30T01:04:31.91+00:00","updated_at":"2026-09-30T00:49:31.91+00:00","request_date":"2026-09-30"}','2026-09-30T00:49:31.91+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2024-04-08','2024-04-08',2024,4,8,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2024-04-08T08:48:00-CME-001","note":"The first in a series of two narrow CMEs, which can be seen only in running difference imagery (not discernible in the white light imagery). The CME is completely covered by the data gap in STEREO A imagery spanning the interval from 2024-04-08T10:09Z to 17:09Z. The source for this CME has not been found on the Earth-facing disk.","start_time":"2024-04-08T08:48Z","source_location":""},{"id":"2024-04-08T10:00:00-CME-001","note":"Second in the series of two narrow eastern CMEs only seen in running difference imagery and not seen in the white light imagery. This CME is completely covered by a data gap in STEREO A imagery. No source for this CME has been found on the Earth-facing disk.","start_time":"2024-04-08T10:00Z","source_location":""},{"id":"2024-04-08T12:36:00-CME-001","note":"Faint fast eastern CME seen in SOHO LASCO C2 running difference imagery and in the white light imagery in C3. The CME is completely covered by a data gap in STEREO A imagery from 2024-04-08T10:09Z to 17:09Z. No on-disk source has been found for this event, but there is a very gradual eruption/ejecta off the southeast limb, as seen in SDO AIA 304 and AIA composite imagery starting after 2024-04-08T06:30Z. However, this eruption seems to be happening too early to be the source of this CME. One spe","start_time":"2024-04-08T12:36Z","source_location":""}],"level":"Moderate","counts":{"cmes":3,"flares":0,"storms":0},"flares":[],"status":"ok","storms":[],"max_flare_class":null},"cache_key":"donki:2024-04-08","created_at":"2026-09-28T08:33:04.919264+00:00","expires_at":"2026-09-28T08:48:04.368+00:00","updated_at":"2026-09-28T08:33:04.368+00:00","request_date":"2024-04-08"}','2026-09-28T08:33:04.368+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2024-12-10','2024-12-10',2024,12,10,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2024-12-10T00:24:00-CME-001","note":"This CME is visible to the south/southeast in SOHO LASCO C2/C3 and STEREO A COR2 imagery. The source may be related to a faint and minor eruption centered near S50E40 as seen in GOES SUVI 304 imagery around 2024-12-09T23:10Z.","start_time":"2024-12-10T00:24Z","source_location":"S50E40"},{"id":"2024-12-10T03:23:00-CME-001","note":"Narrow CME associated with a thin, southward deflecting ejecta seen in the SSE in SUVI 304 around 02:52 and possibly associated with the C9.7 from AR 3922. This southward directed deflection of ejecta and CME is peculiar to today''s events from Active Region 3922.","start_time":"2024-12-10T03:23Z","source_location":"S18E77"},{"id":"2024-12-10T07:00:00-CME-001","note":"A relatively narrow CME associated withthe M6.4 flare from AR 3922 (S18E72), with a narrow southward-deflecting ejecta from this AR seen in GOES SUVI 304 starting at 2024-12-10T04:48Z. Because the sequence of flare/ejecta/CME events is very fast for this and the 2024-12-10T07:24Z CME the attribution to the linked flare is not absolutely certain.","start_time":"2024-12-10T07:00Z","source_location":"S18E72"},{"id":"2024-12-10T07:24:00-CME-001","note":"This CME is likely associated with the M1.4 flare from AR 3922 (S18E72) and is also associated with a thin southward-deflecting ejecta from this AR seen in the southwest in GOES SUVI 304 imagery starting at 2024-12-10T07:16Z but best seen after 07:28Z. Because the sequence of flare/ejecta/CME events is very fast for this and the 2024-12-10T07:00Z CME (which is associated to the preceding M5.6 flare from the same active region), the exact attribution to the linked flare for these two CMEs is not ","start_time":"2024-12-10T07:24Z","source_location":"S18E72"},{"id":"2024-12-10T09:53:00-CME-001","note":"A very slow CME/outflow that follows even slower outflows/fronts that start as early as 2024-12-10T02Z. The source of it could be continuous activity in AR 3920 since this morning (~ location N22E37 at 02Z) which is marked by brightening in SUVI 195. After 08Z there is a minor dimming around this Active Region which could mark the eruption that might be associated with the 2024-12-10T09:53Z front.","start_time":"2024-12-10T09:53Z","source_location":"N22E37"},{"id":"2024-12-10T11:12:00-CME-001","note":"Narrow CME associated with M1.5 flare from AR 3922 (S18E72) and a narrow but eventually fan-shaped wide, south-deflecting ejecta from this AR seen in the southeast in SUVI 304/284 and on southeast limb in EUVI A 195 starting at 2024-12-10T11:00Z.","start_time":"2024-12-10T11:12Z","source_location":"S18E72"}],"level":"Elevated","counts":{"cmes":13,"flares":6,"storms":0},"flares":[{"id":"2024-12-10T03:12:00-FLR-001","peak_time":"2024-12-10T03:27Z","begin_time":"2024-12-10T03:12Z","class_type":"C9.7","source_location":"S18E77"},{"id":"2024-12-10T06:36:00-FLR-001","peak_time":"2024-12-10T06:48Z","begin_time":"2024-12-10T06:36Z","class_type":"M6.4","source_location":"S18E72"},{"id":"2024-12-10T07:03:00-FLR-001","peak_time":"2024-12-10T07:09Z","begin_time":"2024-12-10T07:03Z","class_type":"M1.4","source_location":"S18E72"},{"id":"2024-12-10T10:55:00-FLR-001","peak_time":"2024-12-10T11:02Z","begin_time":"2024-12-10T10:55Z","class_type":"M1.5","source_location":"S18E72"},{"id":"2024-12-10T14:36:00-FLR-001","peak_time":"2024-12-10T14:43Z","begin_time":"2024-12-10T14:36Z","class_type":"C2.8","source_location":"N22E27"},{"id":"2024-12-10T17:54:00-FLR-001","peak_time":"2024-12-10T17:58Z","begin_time":"2024-12-10T17:54Z","class_type":"M1.6","source_location":"S18E70"}],"status":"ok","storms":[],"max_flare_class":"M6.4"},"cache_key":"donki:2024-12-10","created_at":"2026-09-28T10:57:40.940341+00:00","expires_at":"2026-09-28T11:12:40.911+00:00","updated_at":"2026-09-28T10:57:40.911+00:00","request_date":"2024-12-10"}','2026-09-28T10:57:40.911+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2025-02-27','2025-02-27',2025,2,27,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2025-02-27T00:12:00-CME-001","note":"This CME is visible to the west/southwest in SOHO LASCO C2/C3 imagery. This event is not observable in STEREO A COR2 due to a data gap. The source is likely related to a C3.5 flare and eruption from Active Region 13996 (S16W86) starting around 2025-02-26T22:50Z as seen in SDO AIA 131 imagery. Faint field line movement is visible over the southwest limb at this time in SDO AIA 171 and 193 imagery as well.","start_time":"2025-02-27T00:12Z","source_location":"S16W86"},{"id":"2025-02-27T06:23:00-CME-001","note":"This CME is visible to the southwest in STEREO A COR2 and SOHO LASCO C3 imagery. It is also visible in SOHO LASCO C2 following a data gap ending at 2025-02-27T07:48Z. The source is likely related to an eruption from Active Region 13996 (S16W89) starting around 2025-02-27T05:00Z as seen in SDO AIA 131 and 304 imagery. Faint field line movement is visible over the southwest limb around this time in SDO AIA 171 and 193 imagery as well.","start_time":"2025-02-27T06:23Z","source_location":"S16W89"},{"id":"2025-02-27T07:23:00-CME-001","note":"Very faint and wide loop CME first seen to the NW in STEREO A COR2 and seen after a data gap in SOHO LASCO C2. The leading edge is nearly fully obstructed by the pylon in SOHO LASCO C3. Source is likely opening loops and field line movement seen just beyond the (STEREO A) northwest limb in STEREO A EUVI 195 and 304 imagery, starting around 2025-02-27T06:25Z and located at about N20W120 (Earth-facing disk coordinates).","start_time":"2025-02-27T07:23Z","source_location":""},{"id":"2025-02-27T12:00:00-CME-001","note":"CME visible to the southwest in SOHO LASCO C2/C3 and STEREO A COR2. The source is likely Active Region 13996 (S16W90), with an eruption seen starting around 2025-02-27T11:05Z in STEREO A EUVI 195 and SDO AIA 193 imagery. Brightening and dimming are seen from the region, and opening field lines are best seen in SDO AIA 171/193/284.","start_time":"2025-02-27T12:00Z","source_location":"S16W90"},{"id":"2025-02-27T19:12:00-CME-001","note":"CME visible to the northeast in SOHO LASCO C2/C3. Not visible in STEREO A COR2 due to a data gap starting at 2025-02-27T15:23Z. The source is a filament eruption, with liftoff starting around 2025-02-27T17:36Z, centered around approximately N20E80 as seen in SDO AIA 304. Moving/opening field lines are also visible in SDO AIA 171/193 and dimming is visible in SDO AIA 193.","start_time":"2025-02-27T19:12Z","source_location":""}],"level":"Elevated","counts":{"cmes":5,"flares":0,"storms":1},"flares":[],"status":"ok","storms":[{"id":"2025-02-27T09:00:00-GST-001","kp":[{"source":"NOAA","kpIndex":5.67,"observedTime":"2025-02-27T12:00Z"}],"start_time":"2025-02-27T09:00Z"}],"max_flare_class":null},"cache_key":"donki:2025-02-27","created_at":"2026-09-28T10:57:48.006755+00:00","expires_at":"2026-09-28T11:12:47.975+00:00","updated_at":"2026-09-28T10:57:47.975+00:00","request_date":"2025-02-27"}','2026-09-28T10:57:47.975+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2025-02-28','2025-02-28',2025,2,28,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2025-02-28T08:00:00-CME-001","note":"CME first seen the the SW by SOHO LASCO C2 beginning at 2025-02-28T08:00Z, as well as by SOHO LASCO C3 and STEREO A COR2 in later frames. The source of this event is field line opening seen just beyond the SW limb in SDO AIA 193. This may be related to activity from AR 3996 (S16W100) which rotated off of the Earth facing disk on 2025-02-27.","start_time":"2025-02-28T08:00Z","source_location":"S16W100"},{"id":"2025-02-28T15:23:00-CME-001","note":"CME first seen in the NE by STEREO A COR2 beginning at 2025-02-28T15:23Z, as well as by SOHO LASCO C3 in later frames. This CME is not visible in SOHO LASCO C2 due to a data gap from 28/14:48Z to 28/16:24Z. The source of this event is a jet-like eruption from Active Region 4006 (N18W02), exhibiting a very strong Northeastern deflection in SDO AIA and GOES SUVI 304.","start_time":"2025-02-28T15:23Z","source_location":"N18W02"},{"id":"2025-02-28T17:12:00-CME-001","note":"Bright, partial halo to halo CME visible in the W/NW of SOHO LASCO C2, C3, and STEREO A COR2 imagery. The source is a far-sided filament eruption visible along the NW limb of STEREO A EUVI 304 and 195 starting around 2025-02-28T16:45Z. Post eruptive arcades are also visible in STEREO A EUVI 304 and 195 starting around 2025-02-28T17:35Z. Moving/opening field lines and an EUV wave is visible in GOES SUVI 284 starting around 2025-02-28T17:00Z. The source is suspected to be from AR 13993 (~N15W125) ","start_time":"2025-02-28T17:12Z","source_location":""},{"id":"2025-02-28T17:24:00-CME-001","note":"CME first seen in the NE by SOHO LASCO C2 beginning at 2025-02-28T16:48Z, as well as by SOHO LASCO C3 and STEREO A COR2 in later frames. The source of this event is a C5.2 flare and jet-like eruption from Active Region 4006 (N18W02), exhibiting a very strong Northeastern deflection in SDO AIA and GOES SUVI 304. This CME partially overlaps and is obscured by CME: 2025-02-28T17:12Z in later frames.","start_time":"2025-02-28T17:24Z","source_location":"N18W02"}],"level":"Moderate","counts":{"cmes":4,"flares":1,"storms":0},"flares":[{"id":"2025-02-28T16:18:00-FLR-001","peak_time":"2025-02-28T16:28Z","begin_time":"2025-02-28T16:18Z","class_type":"C5.2","source_location":"N18W02"}],"status":"ok","storms":[],"max_flare_class":"C5.2"},"cache_key":"donki:2025-02-28","created_at":"2026-09-28T10:57:50.321292+00:00","expires_at":"2026-09-28T11:12:50.283+00:00","updated_at":"2026-09-28T10:57:50.283+00:00","request_date":"2025-02-28"}','2026-09-28T10:57:50.283+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2026-02-08','2026-02-08',2026,2,8,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-02-08T08:00:00-CME-001","note":"Narrow CME first seen to the NE by SOHO LASCO C2 beginning at 2026-02-08T08:00Z, as well as by SOHO LASCO C3, GOES CCOR-1 and STEREO A COR2 in later frames. The source of this event is field line opening/movement seen originating from the vicinity of AR14373 (N09E52) beginning at approx. 2026-02-08T07:04Z as seen in SDO AIA 171/193.","start_time":"2026-02-08T08:00Z","source_location":"N09E52"},{"id":"2026-02-08T15:00:00-CME-001","note":"CME first seen to the East by SOHO LASCO C2 beginning at 2026-02-08T15:00Z, as well as by SOHO LASCO C3 and GOES CCOR-1 in later frames. This CME is not visible in STEREO A COR2 likely due to it being directly far sided with respect to STEREO A. The source of this event is field line opening seen along the SE limb beginning around 2026-02-08T14:12Z as seen in SDO AIA 193.","start_time":"2026-02-08T15:00Z","source_location":""},{"id":"2026-02-08T16:12:00-CME-001","note":"Faint CME seen along a NNE streamer first seen in SOHO LASCO C2 beginning at 2026-02-08T16:12Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is a small filament eruption seen along the NNE limb in SDO AIA 304 beginning around 2026-02-08T15:44Z, along with field line opening and post eruptive dimming seen in SDO AIA 171/193.","start_time":"2026-02-08T16:12Z","source_location":""},{"id":"2026-02-08T18:12:00-CME-001","note":"Faint minor CME seen to the SW in SOHO LASCO C2 and a couple of early C3 images before it dissipates. The CME is possibly covered by the pylon in GOES CCOR-1 (or too faint to be seen in this coronagraph); it is covered by the daily data gap in STEREO A COR2. Its source could be a minor opening of field lines on/behind the SW limb at the time seen in SDO AIA 193/304/131, and movement of field line behind the SW limb seen in GOES SUVI 284, however this is not a definitive source.","start_time":"2026-02-08T18:12Z","source_location":""},{"id":"2026-02-08T23:12:00-CME-001","note":"Faint narrow CME/jet seen to the E in SOHO LASCO C2/C3 and GOES CCOR-1. It is fully covered by the night time data gap in STEREO A COR2. No clear source has been found in EUV imagery for this event.","start_time":"2026-02-08T23:12Z","source_location":""}],"level":"Elevated","counts":{"cmes":5,"flares":3,"storms":0},"flares":[{"id":"2026-02-08T11:13:00-FLR-001","peak_time":"2026-02-08T11:18Z","begin_time":"2026-02-08T11:13Z","class_type":"M1.8","source_location":"N18W50"},{"id":"2026-02-08T11:32:00-FLR-001","peak_time":"2026-02-08T11:43Z","begin_time":"2026-02-08T11:32Z","class_type":"M1.7","source_location":"N18W49"},{"id":"2026-02-08T13:46:00-FLR-001","peak_time":"2026-02-08T13:53Z","begin_time":"2026-02-08T13:46Z","class_type":"M2.7","source_location":"N14W50"}],"status":"ok","storms":[],"max_flare_class":"M2.7"},"cache_key":"donki:2026-02-08","created_at":"2026-09-28T10:57:44.58244+00:00","expires_at":"2026-09-28T11:12:44.552+00:00","updated_at":"2026-09-28T10:57:44.552+00:00","request_date":"2026-02-08"}','2026-09-28T10:57:44.552+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','donki:2026-09-27','2026-09-27',2026,9,27,NULL,NULL,'{"source":"NASA CCMC DONKI","payload":{"cmes":[{"id":"2026-09-27T06:36:00-CME-001","note":"CME first seen to the West by SOHO LASCO C2 beginning at 2026-09-27T06:36Z, as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is a small eruption from the vicinity of AR 14534 (N10W95) beginning at approx. 2026-09-27T04:30Z in STEREO A EUVI 195. This CME is likely deflected to the West by a large coronal hole in the vicinity of the eruption.","start_time":"2026-09-27T06:36Z","source_location":"N10W95"},{"id":"2026-09-27T07:00:00-CME-001","note":"CME first seen to the SW by SOHO LASCO C2 beginning at 2026-09-27T07:00Z as well as by SOHO LASCO C3, STEREO A COR2 and GOES CCOR-1 in later frames. The source of this event is minor field line movement and brightening seen located at approx. S30W100-120 beginning at 2026-09-27T06:00Z as seen in STEREO A EUVI 195.","start_time":"2026-09-27T07:00Z","source_location":"S30W110"},{"id":"2026-09-27T09:48:00-CME-001","note":"Narrow CME first seen to the NNE by SOHO LASCO C2 beginning at 2026-09-27T09:48Z, as well as by SOHO LASCO C3, GOES CCOR-1 and to the North by STEREO A COR2. There is no clear source seen for this event as it is likely far sided.","start_time":"2026-09-27T09:48Z","source_location":""},{"id":"2026-09-27T14:48:00-CME-001","note":"Narrow, faint CME first seen to the NE by SOHO LASCO C2 beginning at 2026-09-27T14:48Z, as well as by SOHO LASCO C3 and GOES CCOR-1 in later frames. This CME is not clearly seen in STEREO A COR2 imagery. There is no clear source seen for this event as it is likely far sided, but some faint field line movement can be seen beyond the NE limb in SDO AIA 171 beginning at approx. 2026-09-27T13:45Z.","start_time":"2026-09-27T14:48Z","source_location":""},{"id":"2026-09-27T17:36:00-CME-001","note":"Faint CME observed to the NE in SOHO LASCO C2/C3 and GOES CCOR-1, not observed in STEREO A COR2. The source may be far-sided, observed as slow field line movement over the NE limb in SDO AIA 171 starting around 2026-09-27T15:48Z.","start_time":"2026-09-27T17:36Z","source_location":""},{"id":"2026-09-27T21:00:00-CME-001","note":"Faint CME observed to the NE in SOHO LASCO C2/C3 and GOES CCOR-1, not observed in STEREO A COR2. The source may be on/just beyond the SW limb observed in SDO AIA 171, with two close candidates of field line movement around 2026-09-28T19:51Z and/or 2026-09-27T20:25Z a few degrees to the north.","start_time":"2026-09-27T21:00Z","source_location":""}],"level":"Moderate","counts":{"cmes":6,"flares":0,"storms":0},"flares":[],"status":"ok","storms":[],"max_flare_class":null},"cache_key":"donki:2026-09-27","created_at":"2026-09-28T08:36:41.685754+00:00","expires_at":"2026-09-28T11:36:36.283+00:00","updated_at":"2026-09-28T11:21:36.283+00:00","request_date":"2026-09-27"}','2026-09-28T11:21:36.283+00:00');
