INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nasa_cosmic_cache','media:2025-02-28:3108026597','2025-02-28',2025,2,28,NULL,NULL,'{"source":"NASA Image and Video Library","payload":{"items":[{"title":"Intuitive Machines-2 Lunar Landing News Conference – Thursday, March 6, 2025","center":"JSC","nasa_id":"jsc2025m000013_Intuitive_Machines-2_Lunar_Landing_News_Conference_250306","keywords":["Intuitive Machines-2 Lunar Landing News Conference"],"media_type":"video","description":"NASA and Intuitive Machines hosted a post-landing news conference at 4 p.m. EST Thursday, March 6, 2025, from NASA’s Johnson Space Center in Houston. Participants included Nicky Fox, associate administrator, Science Mission Directorate, NASA Headquarters; Clayton Turner, associate administrator, Space Technology Mission Directorate, NASA Headquarters; Steve Altemus, CEO, Intuitive Machines, and Tim Crain, chief growth officer, Intuitive Machines. Intuitive Machines confirmed its lunar lander, Athena, touched down on the Moon at approximately 12:30 p.m. EST on Thursday, March 6, 2025. The company’s IM-2 mission is part of NASA’s CLPS (Commercial Lunar Payload Services) initiative.   Join NASA as we go forward to the Moon and on to Mars -- discover the latest on Earth, the Solar System and beyond with a weekly update in your inbox.  Subscribe at: https://www.nasa.gov/subscribe ","preview_url":"https://images-assets.nasa.gov/video/jsc2025m000013_Intuitive_Machines-2_Lunar_Landing_News_Conference_250306/jsc2025m000013_Intuitive_Machines-2_Lunar_Landing_News_Conference_250306~large.jpg","date_created":"2025-03-06T00:00:00Z"},{"title":"NASA’s Polar Ice Experiment Paves Way for Future Moon Missions","center":"KSC","nasa_id":"KSC-20250213-MH-NAS01-0001-CLPS_Jackie_Quinn_Polar_Ice_Experiment_Paves_Way_for_Future_Moon_Missions","keywords":["NASA","Artemis","KSC","CLPS","Commercial Lunar Payload Services","PRIME-1","Dr. Jackie Quinn","Jackie Quinn","Kennedy Space Center","Firefly"],"media_type":"video","description":"An innovative NASA experiment is preparing for its journey to the Moon as part of Intuitive Machines’ second launch to the lunar surface. The Polar Resources Ice Mining Experiment-1 (PRIME-1) will be delivered through NASA’s Commercial Lunar Payload Services (CLPS) initiative on the next lunar flight.  Designed to investigate the Moon’s subsurface, PRIME-1 will demonstrate groundbreaking technology to extract and analyze lunar soil, paving the way for sustainable human exploration under NASA’s Artemis campaign. In this video, Jackie Quinn explains how PRIME-1’s two key instruments – the Regolith and Ice Drill for Exploring New Terrains (TRIDENT) and the Mass Spectrometer Observing Lunar Operations (MSOLO) – will work together to search for resources beneath the lunar surface.  The Athena lander, carrying PRIME-1 and other NASA technology demonstrations and science investigations, will la","preview_url":"https://images-assets.nasa.gov/video/KSC-20250213-MH-NAS01-0001-CLPS_Jackie_Quinn_Polar_Ice_Experiment_Paves_Way_for_Future_Moon_Missions/KSC-20250213-MH-NAS01-0001-CLPS_Jackie_Quinn_Polar_Ice_Experiment_Paves_Way_for_Future_Moon_Missions~large.jpg","date_created":"2025-02-13T00:00:00Z"}],"status":"ok"},"cache_key":"media:2025-02-28:3108026597","created_at":"2026-09-28T10:57:49.051583+00:00","expires_at":"2026-09-29T10:57:49.021+00:00","updated_at":"2026-09-28T10:57:49.021+00:00","request_date":"2025-02-28"}','2026-09-28T10:57:49.021+00:00');
