INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','bagmati_language_act',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"bagmati_language_act","metadata":{},"title_en":"Bagmati Province legal context","title_ne":"बागमती प्रदेश कानुनी सन्दर्भ","detail_en":"Bagmati Province''s official-language law allows Nepal Sambat notation in provincial/local correspondence and public notices.","detail_ne":"बागमती प्रदेश सरकारी कामकाजको भाषा ऐन, २०८० ले पत्राचार र सार्वजनिक सूचनामा नेपालभाषाको नेपाल संवत् समेत लेख्न सकिने व्यवस्था उल्लेख गर्छ।","source_url":"https://moial.bagamati.gov.np/storage/866/%E0%A4%AA%E0%A5%8D%E0%A4%B0%E0%A4%A6%E0%A5%87%E0%A4%B6-%E0%A4%B8%E0%A4%B0%E0%A4%95%E0%A4%BE%E0%A4%B0%E0%A5%80-%E0%A4%95%E0%A4%BE%E0%A4%AE%E0%A4%95%E0%A4%BE%E0%A4%9C%E0%A4%95%E0%A5%8B-%E0%A4%AD%E0%A4%BE%E0%A4%B7%E0%A4%BE-%E0%A4%90%E0%A4%A8%2C-%E0%A5%A8%E0%A5%A6%E0%A5%AE%E0%A5%A6.pdf","updated_at":"2026-09-19T00:17:30.835101+00:00","source_level":"province-law","source_authority":"Bagmati Province"}','2026-09-19T00:17:30.835101+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','government_2080_07_27',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"government_2080_07_27","metadata":{},"title_en":"Nepal Sambat in government documents","title_ne":"सरकारी कागजातमा नेपाल संवत्","detail_en":"A Government of Nepal implementation letter records the 2080/07/27 Cabinet decision to include Nepal Sambat where Bikram Sambat is written in government documents.","detail_ne":"नेपाल सरकार मन्त्रिपरिषद्को २०८०/०७/२७ को निर्णयअनुसार विक्रम संवत् उल्लेख गरिने सरकारी कागजातमा नेपाल संवत् समेत उल्लेख गर्ने व्यवस्था कार्यान्वयन गर्न निर्देशन गरिएको छ।","source_url":"https://daobardiya.moha.gov.np/upload/aff702e6cd5af671c163358ce68dce56/files/%E0%A4%A8%E0%A5%87%E0%A4%AA%E0%A4%BE%E0%A4%B2_%E0%A4%B8%E0%A4%82%E0%A4%B5%E0%A4%A4_2_9.pdf","updated_at":"2026-09-19T00:17:30.835101+00:00","source_level":"government-primary","source_authority":"Government of Nepal"}','2026-09-19T00:17:30.835101+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','lunar_structure',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"lunar_structure","metadata":{},"title_en":"Lunar Nepal Sambat structure","title_ne":"चन्द्रमानक नेपाल संवत्","detail_en":"The traditional Nepal Sambat is lunisolar: usually 12 lunar months, sometimes an intercalary 13th month, with rare reduced-month cases.","detail_ne":"चन्द्रमानक नेपाल संवत् सामान्यतः १२ महिनाको हुन्छ; अधिक मासमा १३ महिना र दुर्लभ क्षय अवस्थामा ११ महिना हुन सक्छ। औंसीपछि महिना सुरु भई अर्को औंसीमा समाप्त हुन्छ।","source_url":"https://nepalsambat.org/lunar-calendar/","updated_at":"2026-09-19T00:17:30.835101+00:00","source_level":"cultural-reference","source_authority":"Nepal Sambat cultural reference"}','2026-09-19T00:17:30.835101+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','new_year_1146',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"new_year_1146","metadata":{},"title_en":"Nepal Sambat 1146 New Year","title_ne":"नेपाल संवत् ११४६ प्रारम्भ","detail_en":"The President’s Nepal Sambat 1146 greeting is dated N.S. 1146 Kachhala Thwa Pratipada.","detail_ne":"राष्ट्रपतिको २०८२ कात्तिक ५ को शुभकामना सन्देशमा ने.सं. ११४६ कछलाथ्व प्रतिपदा उल्लेख छ।","source_url":"https://president.gov.np/","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Office of the President of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','npns_current_display',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"npns_current_display","metadata":{},"title_en":"Current Panchanga-body display","title_ne":"पञ्चाङ्ग निकायको हालको प्रदर्शन","detail_en":"The Nepal Panchanga Nirnayak Bikash Samiti website displays a current Nepal Sambat date alongside Bikram Sambat.","detail_ne":"नेपाल पञ्चाङ्ग निर्णायक विकास समितिको वेबसाइटमा नेपाल संवत् मिति दैनिक रूपमा वि.सं. सँगै प्रदर्शन हुन्छ।","source_url":"https://npns.gov.np/","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"official-panchanga-body","source_authority":"Nepal Panchanga Nirnayak Bikash Samiti"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','official_notation_examples',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"official_notation_examples","metadata":{},"title_en":"Current official notation","title_ne":"हालको सरकारी लेखन शैली","detail_en":"Current Office of the President notices use Nepal Sambat year plus month/paksha/tithi notation.","detail_ne":"राष्ट्रपतिको कार्यालयका हालका सूचनामा “ने.सं. ११४६ कछलाथ्व प्रतिपदा”, “वछलाथ्व: पञ्चमी/सप्तमी” र “वछलागा: चतुर्थी” जस्ता लेखन उदाहरण छन्।","source_url":"https://president.gov.np/","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Office of the President of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','sankhadhar_context',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"sankhadhar_context","metadata":{},"title_en":"Sankhadhar Sakhwa historical context","title_ne":"शंखधर साख्वा र ऐतिहासिक स्मरण","detail_en":"The President’s greeting describes the tradition linking Sankhadhar Sakhwa, debt relief and the beginning of a new era.","detail_ne":"राष्ट्रपतिको शुभकामना सन्देशमा शंखधर साख्वाले ऋणमुक्ति र नयाँ युगको सुरुवातसँग नेपाल संवत् प्रचलनमा ल्याएको मान्यता उल्लेख गरिएको छ।","source_url":"https://president.gov.np/","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Office of the President of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','solar_nepal_sambat',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"solar_nepal_sambat","metadata":{"solar_epoch":"2020-10-20","solar_epoch_ns":"1141-01-01"},"title_en":"Modern Solar Nepal Sambat","title_ne":"आधुनिक Solar Nepal Sambat","detail_en":"Modern Solar Nepal Sambat is documented separately; this app keeps the traditional lunar Nepal Sambat as its primary cultural layer.","detail_ne":"आधुनिक solar Nepal Sambat परम्परागत lunar Nepal Sambat सँग छुट्टै प्रणालीका रूपमा दस्तावेज गरिएको छ; एपले परम्परागत lunar मितिलाई मुख्य सांस्कृतिक तह मानेको छ।","source_url":"https://nepalsambat.org/solar-calendar/","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"cultural-reference","source_authority":"Nepal Sambat cultural reference"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','solar_week',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"solar_week","metadata":{},"title_en":"Solar Nepal Sambat weekday names","title_ne":"सौर्यमानक साता नाम","detail_en":"The Solar Nepal Sambat reference documents Nepal Bhasa weekday names from Ninhi through Sanhi.","detail_ne":"Solar Nepal Sambat ले निन्हि, मिन्हि, इनान्हि, सुन्हि, सिँन्हि, लुँन्हि र संन्हि जस्ता नेपालभाषा weekday नाम दस्तावेज गर्छ।","source_url":"https://nepalsambat.org/solar-calendar/","updated_at":"2026-09-19T00:17:30.835101+00:00","source_level":"cultural-reference","source_authority":"Nepal Sambat cultural reference"}','2026-09-19T00:17:30.835101+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','thwa_ga',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"thwa_ga","metadata":{},"title_en":"Thwa and Gā fortnights","title_ne":"थ्व र गाः","detail_en":"The waxing/bright fortnight is Thwa and the waning/dark fortnight is Gā.","detail_ne":"पूर्णिमातर्फको उज्यालो पक्षलाई थ्व र औंसीतर्फको अँध्यारो पक्षलाई गाः भनिन्छ।","source_url":"https://nepalsambat.org/lunar-calendar/","updated_at":"2026-09-19T00:17:30.835101+00:00","source_level":"cultural-reference","source_authority":"Nepal Sambat cultural reference"}','2026-09-19T00:17:30.835101+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','tithi_numbering',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"tithi_numbering","metadata":{},"title_en":"Government tithi numbering","title_ne":"सरकारी तिथि संख्या","detail_en":"The guidance gives numerical notation from Pratipada 1 through Chaturdashi 14, Purnima 15 and Amavasya 30.","detail_ne":"मार्गदर्शनमा प्रतिपदा १ देखि चतुर्दशी १४, पूर्णिमा १५ र औंसी ३० लेख्ने उदाहरण दिइएको छ।","source_url":"https://www.mofaga.gov.np/notice-file/Notices-20240108125907641.pdf","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Government of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','tithi_variability',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"tithi_variability","metadata":{},"title_en":"Tithi variability","title_ne":"तिथि क्षय/वृद्धि","detail_en":"A tithi may repeat or be skipped, so weekday/day context can be necessary for unambiguous notation.","detail_ne":"तिथि घट्न वा बढ्न सक्छ; एउटै तिथि दुई दिन देखिन वा कुनै तिथि लोप हुन सक्छ, त्यसैले बार/दिन सन्दर्भ महत्त्वपूर्ण हुन्छ।","source_url":"https://www.mofaga.gov.np/notice-file/Notices-20240108125907641.pdf","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Government of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','traditional_month_boundary',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"traditional_month_boundary","metadata":{},"title_en":"Traditional month boundary","title_ne":"परम्परागत महिना सीमा","detail_en":"Government guidance describes each traditional lunar month as starting at Pratipada and ending at Amavasya.","detail_ne":"प्रत्येक चान्द्र महिना प्रतिपदाबाट सुरु भई औंसीमा पूरा हुने सरकारी मार्गदर्शनमा उल्लेख छ।","source_url":"https://www.mofaga.gov.np/notice-file/Notices-20240108125907641.pdf","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Government of Nepal"}','2026-09-19T00:11:27.447163+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('nepal_sambat_facts','traditional_year_boundary',NULL,NULL,NULL,NULL,NULL,NULL,'{"fact_key":"traditional_year_boundary","metadata":{},"title_en":"Traditional year boundary","title_ne":"परम्परागत वर्ष सीमा","detail_en":"Government date-writing guidance describes the traditional Nepal Sambat year as beginning on Kartika Shukla Pratipada and completing at Kartika Krishna Amavasya.","detail_ne":"नेपाल संवत् कार्तिक शुक्ल प्रतिपदाबाट सुरु भई कार्तिक कृष्ण औंसीमा वर्ष पूरा हुने सरकारी मिति-लेखन मार्गदर्शनमा उल्लेख छ।","source_url":"https://www.mofaga.gov.np/notice-file/Notices-20240108125907641.pdf","updated_at":"2026-09-19T00:11:27.447163+00:00","source_level":"government","source_authority":"Government of Nepal"}','2026-09-19T00:11:27.447163+00:00');
