INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('news_items','00201cb2ee7fdf2784fc12a0659a0c95fdd2c6d322ae1efd0492c848ea8457a5',NULL,NULL,NULL,NULL,'politics',NULL,'{"id":"00201cb2ee7fdf2784fc12a0659a0c95fdd2c6d322ae1efd0492c848ea8457a5","url":"https://www.bbc.com/nepali/articles/cmgrv7nx41eko?at_medium=RSS&at_campaign=rss","title":"सुरक्षाकर्मीलाई जलविद्युत् आयोजनामा आईपीओको दुई प्रतिशत दिनु कति उचित?","excerpt":"प्रतिनिधि सभाको बुधवारको बैठकमा सम्बोधन गर्ने क्रममा ऊर्जामन्त्री विराजभक्त श्रेष्ठले भोटेकोशी-त्रिशूली नदीमा आएको विनाशकारी बाढीका समयमा सुरक्षाकर्मीले निर्वाह गरेको योगदानलाई उच्च मूल्याङ्कन गर्न उक्त व्यवस्था ल्याउन लागिएको बताएका थिए।","category":"politics","province":null,"image_url":null,"source_id":"bbc-nepali","fetched_at":"2026-09-26T04:03:24.123+00:00","category_raw":"राजनीति","published_at":"2026-09-24T10:59:14+00:00"}','2026-09-26T04:03:24.123+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('news_items','014202fd2e523e13bc4f9453e1b9b099db382ed2546992ff795b6e9d08e307d5',NULL,NULL,NULL,NULL,'world',NULL,'{"id":"014202fd2e523e13bc4f9453e1b9b099db382ed2546992ff795b6e9d08e307d5","url":"https://www.nepalpress.com/2026/09/26/767649/lokesh-bams-aggressive-half-century-against-japan/","title":"जापानविरुद्ध लोकेश बमको आक्रामक अर्धशतक","excerpt":"काठमाडौँ । लोकेश बमले जापानविरुद्ध अर्धशतक बनाएका छन् । एसियन गेम्स पुरुष क्रिकेट अन्तरगत जारी खेलमा उनले घरेलु टोलीविरुद्ध मात्र २२ बलमा अर्धशतक प्रहार गरेका हुन् । उनले ६ छक्का र एक चौका प्रहार गरे । उनको यो टी२० अन्तर्राष्ट्रियमा उनको यो पहिलो अर्धशतक हो ।","category":"world","province":3,"image_url":null,"source_id":"nepalpress","fetched_at":"2026-09-26T04:02:53.998+00:00","category_raw":"विश्व","published_at":"2026-09-26T02:22:41+00:00"}','2026-09-26T04:02:53.998+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('news_items','015ce3f2ac168dfb82cbc64bd609d9291c4c9a9696b2eab1dcce4d23fd04d513',NULL,NULL,NULL,NULL,'province',NULL,'{"id":"015ce3f2ac168dfb82cbc64bd609d9291c4c9a9696b2eab1dcce4d23fd04d513","url":"https://nepalkhabar.com/society/288073-2026-9-26-3-55-2","title":"कमजोर हुँदै छ नेपालमा प्रभाव पारिरहेको भारतको न्यूनचापीय प्रणाली","excerpt":"मौसम पूर्वानुमान महाशाखाले आज शनिबार बिहान ८ बजे अद्यावधिक गरेको बुलेटिअनुसार नेपालमा प्रभाव पारिरहेको&nbsp;भारतको उत्तर छत्तीसगढ तथा उत्तर पूर्वी मध्य प्रदेशमा रहेको न्यूनचापीय प्रणाली (डिप्रेसन) उत्तर-उत्तरपश्चिमतर्फ सर्दै भारतको दक्षिणपूर्वी उत्तर प्रदेशतर्","category":"province","province":null,"image_url":null,"source_id":"nepalkhabar","fetched_at":"2026-09-26T04:02:53.998+00:00","category_raw":"प्रदेश/स्थानीय","published_at":"2026-09-26T04:02:53.998+00:00"}','2026-09-26T04:02:53.998+00:00');
